<script setup lang="ts">import type{Notification}from'@career-launch/shared';import{onMounted,ref}from'vue';import{repository}from'../../services/repository';const items=ref<Notification[]>([]);async function load(){items.value=await repository.notifications.list()}async function markAll(){await repository.notifications.markAllRead();await load()}onMounted(load)</script>
<template><section><header><div><h1>通知中心</h1><p>查看截止提醒、投递变化和系统消息。</p></div><button class="cl-quiet-button" @click="markAll">全部标为已读</button></header><div class="notifications cl-card"><article v-for="item in items" :key="item.id" :class="{unread:!item.read}"><span></span><div><strong>{{item.title}}</strong><p>{{item.body}}</p><small>{{new Date(item.createdAt).toLocaleString('zh-CN')}}</small></div></article></div></section></template><style scoped>header{display:flex;align-items:start;justify-content:space-between;gap:18px}h1{margin:0;font-size:30px}header p,article p,article small{color:var(--cl-muted)}.notifications{margin-top:18px;overflow:hidden}.notifications article{display:grid;grid-template-columns:8px 1fr;gap:12px;padding:18px 20px}.notifications article+article{border-top:1px solid var(--cl-border)}article>span{width:7px;height:7px;margin-top:8px;border-radius:50%;background:transparent}article.unread>span{background:var(--cl-primary)}article p{margin:3px 0}</style>
